package com.alsafa.native4;
import android.app.*;import android.os.Bundle;import android.database.Cursor;import android.content.ContentValues;import android.widget.*;import android.view.*;import com.alsafa.native4.core.*;import org.json.JSONObject;
public final class SyncCenterActivity extends Activity{
 private CoreDb db;private LinearLayout list;private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new CoreDb(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,24,20,12);status=new TextView(this);status.setTextSize(19);root.addView(status);Button sync=new Button(this);sync.setText("مزامنة الآن");root.addView(sync);sync.setOnClickListener(v->{Native4AutoSync.requestImmediate(this,db,this::refresh);refresh();});ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);refresh();}
 @Override protected void onResume(){super.onResume();refresh();}
 private void refresh(){status.setText(Native4AutoSync.status());list.removeAllViews();try(Cursor c=db.db().rawQuery("SELECT operation_id,operation_kind,record_id,payload,state,attempts,last_error FROM outbox ORDER BY created_at DESC LIMIT 200",null)){while(c.moveToNext()){String id=c.getString(0),kind=c.getString(1),record=c.getString(2),payload=c.getString(3),state=c.getString(4),error=c.getString(6);int attempts=c.getInt(5);String label=label(kind,record,payload);Button item=new Button(this);item.setAllCaps(false);item.setText(label+"\n"+stateName(state)+" | محاولات: "+attempts);list.addView(item);item.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(label).setMessage("الحالة: "+stateName(state)+"\nالمعرّف: "+id+"\nعدد المحاولات: "+attempts+"\nالخطأ: "+(error==null?"لا يوجد":error)).setNegativeButton("إغلاق",null).setPositiveButton("إعادة محاولة الرفع",(dialog,which)->retry(id,state)).show());}}catch(Exception e){status.setText("تعذر قراءة العمليات: "+e.getMessage());}}
 private void retry(String id,String state){if("CONFIRMED".equals(state)||"SENDING".equals(state)){new AlertDialog.Builder(this).setMessage("لا يمكن إعادة إرسال عملية مؤكدة أو قيد الإرسال").setPositiveButton("حسنًا",null).show();return;}ContentValues v=new ContentValues();v.put("state","RETRY");int n=db.db().update("outbox",v,"operation_id=? AND state IN ('PENDING','RETRY','FAILED')",new String[]{id});if(n==1)Native4AutoSync.requestImmediate(this,db,this::refresh);refresh();}
 private static String label(String kind,String id,String payload){String type=kind==null?"عملية":kind;switch(type){case "SALE":case "SALE_CREATE":case "SALE_UPDATE":type="مبيع";break;case "REPAIR":case "REPAIR_UPDATE":type="صيانة";break;case "PRODUCT_CREATE":case "PRODUCT_UPDATE":case "PRODUCT_DELETE":type="منتج";break;case "PURCHASE":type="شراء";break;}String name="";try{JSONObject j=new JSONObject(payload);name=type.equals("منتج")?j.optString("name",j.optString("productName","")):type.equals("مبيع")||type.equals("صيانة")?j.optString("invoiceNo",""):type.equals("شراء")?j.optString("invoiceRef",""):"";}catch(Exception ignored){}return type+" — "+(name.isEmpty()?id:name);}
 private static String stateName(String s){if("CONFIRMED".equals(s))return "تم الرفع";if("SENDING".equals(s))return "قيد الرفع";if("FAILED".equals(s))return "فشل";if("RETRY".equals(s))return "بانتظار إعادة المحاولة";return "بانتظار الرفع";}
}